[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\fill[gray!35] (-2,0) -- (-2,2) -- plot[smooth,domain=-2:4,variable=\x] ({\x},{0.25*\x*\x+1}) -- (4,0) -- cycle;
\draw[->] (-3.2,0) -- (5.2,0) node[right] {$x$};
\draw[->] (0,-0.7) -- (0,6.4) node[above] {$y$};
\draw[thick,<->,domain=-3:4.6,smooth,variable=\x] plot ({\x},{0.25*\x*\x+1});
\node at (-1.6,4.6) {$y=f(x)$};
\foreach \x in {-1.25,-0.5,0.25,1,1.75,2.5,3.25} \draw[dashed] (\x,0) -- (\x,{0.25*\x*\x+1});
\draw (-2,0.15) -- (-2,-0.15) node[below,fill=white,inner sep=1pt] {$-2$};
\draw (4,0.15) -- (4,-0.15) node[below,fill=white,inner sep=1pt] {$4$};
\end{tikzpicture}
