\begin{tikzpicture}[every node/.style={font=\large}, x=0.6cm]
\fill[gray!35] (2,0) -- (2,4) -- plot[smooth,domain=2:8,variable=\x] ({\x},{8/\x}) -- (8,0) -- cycle;
