\begin{tikzpicture}[every node/.style={font=\large}, y=0.2cm]
\fill[gray!35] (2,0) -- (2,4) -- plot[smooth,domain=2:5,variable=\x] ({\x},{\x*\x}) -- (5,0) -- cycle;
\draw[->] (-0.6,0) -- (6.2,0) node[right] {$x$};
